import { test, expect } from '@playwright/test';

test.describe('VetConnect — Authentication & Role Redirection', () => {
  test('loads landing page without console errors', async ({ page }) => {
    const errors: string[] = [];
    page.on('console', (msg) => {
      if (msg.type() === 'error') errors.push(msg.text());
    });
    await page.goto('/');
    await expect(page).toHaveTitle(/VetConnect/i);
    expect(errors).toEqual([]);
  });

  test('blocks unauthenticated access to /client/dashboard and redirects to /login', async ({ page }) => {
    await page.goto('/client/dashboard');
    await expect(page).toHaveURL(/\/login/);
  });
});

import { test, expect } from '@playwright/test';

test.describe('VetConnect — Appointments & Consultation Sync', () => {
  test('verifies compliance pages render properly (/privacy, /terms)', async ({ page }) => {
    await page.goto('/privacy');
    await expect(page.locator('body')).toBeVisible();
    await page.goto('/terms');
    await expect(page.locator('body')).toBeVisible();
  });

  test('validates consultation cancellation sync between Messages and Pets', async ({ page }) => {
    await page.goto('/login');
    await expect(page).toHaveURL(/\/login/);
  });
});
